   199→pub(crate) fn compute_shuffled_index<P: Preset>(
   200→    index: ValidatorIndex,
   201→    index_count: NonZeroU64,
   202→    seed: H256,
   203→) -> ValidatorIndex {
   204→    shuffling::shuffle_single::<P>(index, index_count, seed)
