   207→fn compute_proposer_index_pre_electra<P: Preset>(
   208→    state: &impl BeaconState<P>,
   209→    indices: &PackedIndices,
   210→    seed: H256,
   211→) -> Result<ValidatorIndex> {
   212→    let total = indices
   213→        .len()
   214→        .try_conv::<u64>()?
   215→        .pipe(NonZeroU64::new)
   216→        .ok_or(Error::NoActiveValidators)?;
   217→
   218→    let max_random_byte = u64::from(u8::MAX);
   219→
   220→    (0..u64::MAX / H256::len_bytes() as u64)
   221→        .flat_map(|quotient| {
   222→            hashing::hash_256_64(seed, quotient)
   223→                .to_fixed_bytes()
   224→                .into_iter()
   225→                .map(u64::from)
   226→        })
   227→        .zip(0..)
   228→        .find_map(|(random_byte, attempt)| {
   229→            let shuffled_index_of_index = compute_shuffled_index::<P>(attempt % total, total, seed)
   230→                .try_conv::<usize>()
   231→                .expect(
   232→                    "shuffled_index_of_index fits in usize because it is less than indices.len()",
   233→                );
   234→
   235→            let candidate_index = indices
   236→                .get(shuffled_index_of_index)
   237→                .expect("compute_shuffled_index returns a value less than indices.len()");
   238→
   239→            let effective_balance = state
   240→                .validators()
   241→                .get(candidate_index)
   242→                .expect("candidate_index was produced by enumerating active validators")
   243→                .effective_balance;
   244→
   245→            (effective_balance * max_random_byte >= P::MAX_EFFECTIVE_BALANCE * random_byte)
   246→                .then_some(candidate_index)
   247→        })
   248→        .ok_or(Error::FailedToSelectProposer)
   249→        .map_err(Into::into)
   250→}
   251→
   252→fn compute_proposer_index_post_electra<P: Preset>(
   253→    state: &impl BeaconState<P>,
   254→    indices: &PackedIndices,
   255→    seed: H256,
   256→) -> Result<ValidatorIndex> {
   257→    let total = indices
   258→        .len()
   259→        .try_conv::<u64>()?
   260→        .pipe(NonZeroU64::new)
   261→        .ok_or(Error::NoActiveValidators)?;
   262→
   263→    let max_random_value = u64::from(u16::MAX);
   264→
   265→    (0..u64::MAX / H128::len_bytes() as u64)
   266→        .flat_map(|quotient| {
   267→            hashing::hash_256_64(seed, quotient)
   268→                .to_fixed_bytes()
   269→                .into_iter()
   270→                .tuples()
   271→                .map(|bytes: (u8, u8)| u64::from(u16::from_le_bytes(bytes.into())))
   272→        })
   273→        .zip(0..)
   274→        .find_map(|(random_value, attempt)| {
   275→            let shuffled_index_of_index = compute_shuffled_index::<P>(attempt % total, total, seed)
   276→                .try_conv::<usize>()
   277→                .expect(
   278→                    "shuffled_index_of_index fits in usize because it is less than indices.len()",
   279→                );
   280→
   281→            let candidate_index = indices
   282→                .get(shuffled_index_of_index)
   283→                .expect("compute_shuffled_index returns a value less than indices.len()");
   284→
   285→            let effective_balance = state
   286→                .validators()
   287→                .get(candidate_index)
   288→                .expect("candidate_index was produced by enumerating active validators")
   289→                .effective_balance;
   290→
   291→            (effective_balance * max_random_value
   292→                >= P::MAX_EFFECTIVE_BALANCE_ELECTRA * random_value)
   293→                .then_some(candidate_index)
   294→        })
   295→        .ok_or(Error::FailedToSelectProposer)
   296→        .map_err(Into::into)
   297→}
   298→
   299→pub(crate) fn compute_proposer_index<P: Preset>(
   300→    config: &Config,
   301→    state: &impl BeaconState<P>,
   302→    indices: &PackedIndices,
   303→    seed: H256,
   304→    epoch: Epoch,
   305→) -> Result<ValidatorIndex> {
   306→    if state.is_post_electra() || epoch >= config.electra_fork_epoch {
   307→        compute_proposer_index_post_electra(state, indices, seed)
   308→    } else {
   309→        compute_proposer_index_pre_electra(state, indices, seed)
   310→    }
   311→}
