   330→/// [`compute_subnet_for_blob_sidecar`](https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.1/specs/deneb/validator.md#sidecar)
   331→pub fn compute_subnet_for_blob_sidecar<P: Preset>(
   332→    config: &Config,
   333→    blob_sidecar: &BlobSidecar<P>,
   334→) -> SubnetId {
   335→    let phase = config.phase_at_slot::<P>(blob_sidecar.signed_block_header.message.slot);
   336→
   337→    blob_sidecar.index % config.blob_sidecar_subnet_count(phase)
   338→}
   339→
   340→// source: https://github.com/ethereum/consensus-specs/pull/3574/files/cebf78a83e6fc8fa237daf4264b9ca0fe61473f4#diff-96cf4db15bede3d60f04584fb25339507c35755959159cdbe19d760ca92de109R106
   341→#[must_use]
   342→pub const fn compute_subnet_for_data_column_sidecar(
   343→    config: &Config,
   344→    column_index: ColumnIndex,
   345→) -> SubnetId {
   346→    column_index % config.data_column_sidecar_subnet_count
   347→}
   348→
   349→/// <https://github.com/ethereum/consensus-specs/blob/v1.1.0/specs/altair/validator.md#broadcast-sync-committee-message>
   350→pub fn compute_subnets_for_sync_committee<P: Preset>(
   351→    state: &(impl PostAltairBeaconState<P> + ?Sized),
   352→    validator_index: ValidatorIndex,
   353→) -> Result<BitVector<SyncCommitteeSubnetCount>> {
   354→    let next_slot_epoch = compute_epoch_at_slot::<P>(state.slot() + 1);
   355→
   356→    let sync_committee = if sync_committee_period::<P>(accessors::get_current_epoch(state))
   357→        == sync_committee_period::<P>(next_slot_epoch)
   358→    {
   359→        state.current_sync_committee()
   360→    } else {
   361→        state.next_sync_committee()
   362→    };
   363→
   364→    let target_pubkey = &state.validators().get(validator_index)?.pubkey;
   365→
   366→    let mut subnets = BitVector::default();
   367→
   368→    sync_committee
   369→        .pubkeys
   370→        .iter()
   371→        .enumerate()
   372→        .filter(|(_, pubkey)| *pubkey == target_pubkey)
   373→        .map(|(position, _)| position.div_typenum::<SyncSubcommitteeSize<P>>())
   374→        .for_each(|position| subnets.set(position, true));
   375→
   376→    Ok(subnets)
   377→}
