   379→/// [`compute_subscribed_subnets`](https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.2/specs/phase0/p2p-interface.md#attestation-subnet-subscription)
   380→pub fn compute_subscribed_subnets<P: Preset>(
   381→    node_id: NodeId,
   382→    config: &Config,
   383→    epoch: Epoch,
   384→) -> Result<impl Iterator<Item = SubnetId>> {
   385→    let attestation_subnet_prefix_bits = AttestationSubnetCount::USIZE
   386→        .ilog2_ceil()
   387→        .checked_add(config.attestation_subnet_extra_bits)
   388→        .ok_or(Error::SubnetPrefixBitCountOverflow)?;
   389→
   390→    let node_id_prefix = node_id
   391→        .shr(NodeId::BITS - u16::from(attestation_subnet_prefix_bits))
   392→        .try_into()?;
   393→
   394→    let node_offset = node_id % config.epochs_per_subnet_subscription;
   395→
   396→    let permutation_seed = (node_offset + Uint256::from_u64(epoch))
   397→        .div(config.epochs_per_subnet_subscription)
   398→        .try_into()
   399→        .map(hashing::hash_64)?;
   400→
   401→    let permutated_prefix_maximum = 1_u64
   402→        .checked_shl(attestation_subnet_prefix_bits.into())
   403→        .ok_or(Error::PermutatedPrefixMaximumOverflow)?
   404→        .try_into()?;
   405→
   406→    let permutated_prefix =
   407→        compute_shuffled_index::<P>(node_id_prefix, permutated_prefix_maximum, permutation_seed);
   408→
   409→    let cutoff = permutated_prefix
   410→        .checked_add(config.subnets_per_node)
   411→        .ok_or(Error::SubnetIdOverflow)?;
   412→
   413→    Ok((permutated_prefix..cutoff).map(|index| index % AttestationSubnetCount::U64))
   414→}
   415→
   416→pub fn next_subnet_subscription_epoch<P: Preset>(
   417→    node_id: NodeId,
   418→    config: &Config,
   419→    current_epoch: Epoch,
   420→) -> Result<Epoch> {
   421→    let current_subscribed_subnets =
   422→        compute_subscribed_subnets::<P>(node_id, config, current_epoch)?.collect_vec();
   423→
   424→    let mut epoch = current_epoch + 1;
   425→
   426→    while compute_subscribed_subnets::<P>(node_id, config, epoch)?.collect_vec()
   427→        == current_subscribed_subnets
   428→    {
   429→        epoch += 1;
   430→    }
   431→
   432→    Ok(epoch)
   433→}
