   435→/// [`compute_time_at_slot`] and [`compute_timestamp_at_slot`].
   436→///
   437→/// The two functions do the same thing as long as [`GENESIS_SLOT`] is 0.
   438→/// [`compute_timestamp_at_slot`] was originally an exact duplicate of [`compute_time_at_slot`].
   439→/// See:
   440→/// - <https://github.com/ethereum/consensus-specs/commit/0dec828d89c522aa2048e47f681eccb41b5fa282#diff-1ca740c05fe970719353cb1588c2158b04257ed260017d6464c315eeba35e099R162-R167>
   441→/// - <https://github.com/ethereum/consensus-specs/commit/f6f36872d82d15e6b3ee2a9afc0fd949f4e9ad13>
   442→/// - <https://github.com/ethereum/consensus-specs/commit/878b15df6ab8d56dd4499c45e2ddec4faa570910>
   443→/// - <https://github.com/ethereum/consensus-specs/commit/65649c0383c886b11beac6f0fb58bad19ffc2f7e>
   444→///
   445→/// [`compute_time_at_slot`]:      https://github.com/ethereum/consensus-specs/blob/9839ed49346a85f95af4f8b0cb9c4d98b2308af8/specs/phase0/validator.md#get_eth1_data
   446→/// [`compute_timestamp_at_slot`]: https://github.com/ethereum/consensus-specs/blob/9839ed49346a85f95af4f8b0cb9c4d98b2308af8/specs/bellatrix/beacon-chain.md#compute_timestamp_at_slot
   447→#[must_use]
   448→pub fn compute_timestamp_at_slot<P: Preset>(
   449→    config: &Config,
   450→    state: &(impl BeaconState<P> + ?Sized),
   451→    slot: Slot,
   452→) -> UnixSeconds {
   453→    let slots_since_genesis = slot - GENESIS_SLOT;
   454→    state.genesis_time() + slots_since_genesis * config.slot_duration_ms.as_secs()
   455→}
