   492→/// [`kzg_commitment_to_versioned_hash`](https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.1/specs/deneb/beacon-chain.md#kzg_commitment_to_versioned_hash)
   493→#[must_use]
   494→pub fn kzg_commitment_to_versioned_hash(kzg_commitment: KzgCommitment) -> VersionedHash {
   495→    // TODO(feature/deneb): Implement `AsRef` directly on `KzgCommitment` like with `PublicKeyBytes`.
   496→    //                      See the TODO in `types::deneb::primitives`.
   497→    struct Wrapper(KzgCommitment);
   498→
   499→    impl AsRef<[u8; 48]> for Wrapper {
   500→        fn as_ref(&self) -> &[u8; 48] {
   501→            self.0.as_fixed_bytes()
   502→        }
   503→    }
   504→
   505→    let mut versioned_hash = hashing::hash_384(Wrapper(kzg_commitment));
   506→    versioned_hash[..VERSIONED_HASH_VERSION_KZG.len()].copy_from_slice(VERSIONED_HASH_VERSION_KZG);
   507→    versioned_hash
   508→}
