   675→pub fn construct_blob_sidecar<P: Preset>(
   676→    block: &SignedBeaconBlock<P>,
   677→    signed_block_header: SignedBeaconBlockHeader,
   678→    index: BlobIndex,
   679→    blob: Blob<P>,
   680→    kzg_commitment: KzgCommitment,
   681→    kzg_proof: KzgProof,
   682→) -> Result<BlobSidecar<P>> {
   683→    let message = block.message();
   684→
   685→    let Some(body) = message.body().post_deneb() else {
   686→        return Err(Error::BlobsForPreDenebBlock {
   687→            root: message.hash_tree_root(),
   688→            slot: message.slot(),
   689→        }
   690→        .into());
   691→    };
   692→
   693→    let kzg_commitment_inclusion_proof = match message.body().post_electra() {
   694→        Some(body) => electra_kzg_commitment_inclusion_proof(body, index)?,
   695→        None => deneb_kzg_commitment_inclusion_proof(body, index)?,
   696→    };
   697→
   698→    Ok(BlobSidecar {
   699→        index,
   700→        blob,
   701→        kzg_commitment,
   702→        kzg_proof,
   703→        signed_block_header,
   704→        kzg_commitment_inclusion_proof,
   705→    })
   706→}
   707→
   708→pub fn construct_blob_sidecars<P: Preset>(
   709→    block: &SignedBeaconBlock<P>,
   710→    blobs: impl IntoIterator<Item = Blob<P>>,
   711→    proofs: impl IntoIterator<Item = KzgProof>,
   712→) -> Result<Vec<BlobSidecar<P>>> {
   713→    let Some(body) = block.message().body().post_deneb() else {
   714→        return Ok(vec![]);
   715→    };
   716→
   717→    let commitments = body.blob_kzg_commitments().into_iter().copied();
   718→    let signed_block_header = block.to_header();
   719→
   720→    izip!(0.., blobs, proofs, commitments)
   721→        .map(|(index, blob, kzg_proof, kzg_commitment)| {
   722→            construct_blob_sidecar(
   723→                block,
   724→                signed_block_header,
   725→                index,
   726→                blob,
   727→                kzg_commitment,
   728→                kzg_proof,
   729→            )
   730→        })
   731→        .collect()
   732→}
