   735→pub fn committee_index<P: Preset>(attestation: &Attestation<P>) -> CommitteeIndex {
   736→    match attestation {
   737→        Attestation::Phase0(attestation) => attestation.data.index,
   738→        Attestation::Electra(attestation) => get_committee_indices::<P>(attestation.committee_bits)
   739→            .next()
   740→            .unwrap_or_default(),
   741→        Attestation::Single(attestation) => attestation.committee_index,
   742→    }
   743→}
