   745→pub fn get_committee_indices<P: Preset>(
   746→    committee_bits: BitVector<P::MaxCommitteesPerSlot>,
   747→) -> impl Iterator<Item = CommitteeIndex> {
   748→    committee_bits
   749→        .into_iter()
   750→        .zip(0..)
   751→        .filter_map(|(present, committee_index)| present.then_some(committee_index))
   752→}
