   785→pub fn compute_matrix_for_data_column_sidecar<P: Preset>(
   786→    data_column_sidecar: &DataColumnSidecar<P>,
   787→) -> Vec<MatrixEntry<P>> {
   788→    let DataColumnSidecar {
   789→        index,
   790→        column,
   791→        kzg_proofs,
   792→        ..
   793→    } = data_column_sidecar;
   794→
   795→    let blob_count = column.len() as u64;
   796→
   797→    izip!(0..blob_count, column, kzg_proofs)
   798→        .map(|(row_index, cell, kzg_proof)| MatrixEntry {
   799→            row_index,
   800→            column_index: *index,
   801→            cell: cell.clone(),
   802→            kzg_proof: *kzg_proof,
   803→        })
   804→        .collect()
   805→}
