   807→pub fn compute_proposer_indices<P: Preset>(
   808→    config: &Config,
   809→    state: &impl BeaconState<P>,
   810→    epoch: Epoch,
   811→    seed: H256,
   812→    indices: &PackedIndices,
   813→) -> Result<Vec<ValidatorIndex>> {
   814→    let start_slot = compute_start_slot_at_epoch::<P>(epoch);
   815→    (0..P::SlotsPerEpoch::U64)
   816→        .map(|i| {
   817→            let seed = hashing::hash_256_64(seed, start_slot.saturating_add(i));
   818→            compute_proposer_index(config, state, indices, seed, epoch)
   819→        })
   820→        .collect::<Result<_>>()
   821→}
